        // Calculates completion percentage using modules
        // belonging to the trainee's enrolled programs.
        public async Task<double> GetCompletionPercentageAsync(int traineeId)
        {
            // Get distinct programs associated with the trainee's enrollments.
            var enrolledProgramIds = _context.NFD_Enrollments
                .AsNoTracking()
                .Where(e => e.TraineeId == traineeId)
                .Select(e => e.Batch.ProgramId)
                .Distinct();

            // Include only non-archived modules from enrolled programs.
            var eligibleModuleIds = _context.NFD_Modules
                .AsNoTracking()
                .Where(m =>
                    !m.IsArchived &&
                    enrolledProgramIds.Contains(m.ProgramId))
                .Select(m => m.ModuleId);

            // Count modules relevant to the trainee.
            var totalModules = await eligibleModuleIds.CountAsync();

            if (totalModules == 0)
            {
                return 0;
            }

            // Count distinct completed modules from the same set.
            var completedModules = await _context.NFD_TraineeModuleProgresses
                .AsNoTracking()
                .Where(p =>
                    p.TraineeId == traineeId &&
                    p.Status == Enums.NFD_ModuleProgressStatus.Completed &&
                    eligibleModuleIds.Contains(p.ModuleId))
                .Select(p => p.ModuleId)
                .Distinct()
                .CountAsync();

            // Return percentage rounded to two decimal places.
            return Math.Round(
                (double)completedModules / totalModules * 100,
                2
            );
        }
